```tsx
import type { ReactElement } from "react";
import "./ButtonRow.css";

export interface ButtonRowProps {
  primaryLabel: string;
  onPrimary: () => void;
  primaryDisabled?: boolean;

  secondaryLabel: string;
  onSecondary: () => void;
  secondaryDisabled?: boolean;

  quietLabel: string;
  onQuiet: () => void;
  quietDisabled?: boolean;
}

export function ButtonRow({
  primaryLabel,
  onPrimary,
  primaryDisabled = false,
  secondaryLabel,
  onSecondary,
  secondaryDisabled = false,
  quietLabel,
  onQuiet,
  quietDisabled = false,
}: ButtonRowProps): ReactElement {
  return (
    <div className="myelin-button-row" role="group">
      <button
        type="button"
        className="myelin-button myelin-button--primary"
        onClick={onPrimary}
        disabled={primaryDisabled}
      >
        {primaryLabel}
      </button>
      <button
        type="button"
        className="myelin-button myelin-button--secondary"
        onClick={onSecondary}
        disabled={secondaryDisabled}
      >
        {secondaryLabel}
      </button>
      <button
        type="button"
        className="myelin-button myelin-button--quiet"
        onClick={onQuiet}
        disabled={quietDisabled}
      >
        {quietLabel}
      </button>
    </div>
  );
}
```

