/* Day theme tokens (default) */
.myelin-button-row {
  --mbr-accent: #4f6b5a;
  --mbr-accent-hover: #435c4d;
  --mbr-on-accent: #fbfaf6;
  --mbr-ink: #2b2a27;
  --mbr-ink-muted: #6b6860;
  --mbr-border: #c9c3b4;
  --mbr-surface-hover: #ebe6d9;
  --mbr-disabled-ink: #a7a296;
  --mbr-disabled-border: #dcd7ca;
  --mbr-disabled-fill: #efebe2;
  --mbr-focus: #2f5bd1;

  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  font-family: inherit;
}

/* Night theme tokens */
[data-theme="night"] .myelin-button-row {
  --mbr-accent: #8fb39b;
  --mbr-accent-hover: #a3c4ad;
  --mbr-on-accent: #14171a;
  --mbr-ink: #e6e2d8;
  --mbr-ink-muted: #a6a194;
  --mbr-border: #4a4d52;
  --mbr-surface-hover: #262a2f;
  --mbr-disabled-ink: #5d6167;
  --mbr-disabled-border: #32363b;
  --mbr-disabled-fill: #1f2226;
  --mbr-focus: #9bb8ff;
}

/* Shared button base */
.myelin-button {
  appearance: none;
  box-sizing: border-box;
  min-height: 44px;
  padding: 10px 20px;
  font: inherit;
  font-size: 0.95rem;
  line-height: 1.2;
  letter-spacing: 0.01em;
  border-radius: 999px;
  cursor: pointer;
  transition:
    background-color 160ms ease,
    color 160ms ease,
    border-color 160ms ease;
}

.myelin-button:focus-visible {
  outline: 2px solid var(--mbr-focus);
  outline-offset: 3px;
}

.myelin-button:disabled {
  cursor: not-allowed;
}

/* Primary: filled accent */
.myelin-button--primary {
  background-color: var(--mbr-accent);
  color: var(--mbr-on-accent);
  border: 1px solid var(--mbr-accent);
  font-weight: 600;
}

.myelin-button--primary:hover:not(:disabled) {
  background-color: var(--mbr-accent-hover);
  border-color: var(--mbr-accent-hover);
}

.myelin-button--primary:disabled {
  background-color: var(--mbr-disabled-fill);
  border-color: var(--mbr-disabled-border);
  color: var(--mbr-disabled-ink);
}

/* Secondary: outlined */
.myelin-button--secondary {
  background-color: transparent;
  color: var(--mbr-ink);
  border: 1px solid var(--mbr-border);
  font-weight: 500;
}

.myelin-button--secondary:hover:not(:disabled) {
  background-color: var(--mbr-surface-hover);
}

.myelin-button--secondary:disabled {
  background-color: transparent;
  border-color: var(--mbr-disabled-border);
  color: var(--mbr-disabled-ink);
}

/* Quiet: text only */
.myelin-button--quiet {
  background-color: transparent;
  color: var(--mbr-ink-muted);
  border: 1px solid transparent;
  padding-left: 12px;
  padding-right: 12px;
  font-weight: 500;
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 4px;
}

.myelin-button--quiet:hover:not(:disabled),
.myelin-button--quiet:focus-visible {
  color: var(--mbr-ink);
  text-decoration-color: currentColor;
}

.myelin-button--quiet:disabled {
  color: var(--mbr-disabled-ink);
  text-decoration-color: transparent;
}

@media (prefers-reduced-motion: reduce) {
  .myelin-button {
    transition: none;
  }
}
